INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần, để chế độ tiêu chuẩn mặc định là giặt sạch lắm rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Dạ hiểu rồi, cảm ơn chị nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程；退款不会即时处理，学校后勤固定日期批量结算。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚在宿舍楼自助洗衣房洗衣服，机器运行一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng zài sù shè lóu zì zhù xǐ yī fáng xǐ yī fú， jī qì yùn xíng yí bàn tū rán tíng jī le。','Cô ơi, con vừa giặt đồ ở phòng giặt tự động của ký túc xá, máy đang chạy nửa chừng thì tự dưng dừng lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'别着急，你先回忆一下，机器停机的时候屏幕有没有弹出提示文字？','bié zháo jí， nǐ xiān huí yì yī xià， jī qì tíng jī de shí hòu píng mù yǒu méi yǒu dàn chū tí shì wén zì？','Đừng lo, con thử nhớ lại xem lúc máy dừng màn hình có hiện chữ thông báo gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'屏幕显示账户余额不足，自动中断洗涤程序，衣服只洗了一半。','píng mù xiǎn shì zhàng hù yú é bù zú， zì dòng zhōng duàn xǐ dí chéng xù， yī fú zhǐ xǐ le yí bàn。','Màn hình báo là số dư tài khoản không đủ nên tự động ngắt chương trình giặt, đồ mới giặt được có một nửa thôi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'原来是扣费余额耗尽，这种情况在自助设备使用里十分常见。','yuán lái shì kòu fèi yú é hào jìn， zhè zhǒng qíng kuàng zài zì zhù shè bèi shǐ yòng lǐ shí fēn cháng jiàn。','À ra là hết tiền trong tài khoản, trường hợp này với máy tự động thì gặp hoài đó con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'我之前查看余额还有几块钱，以为完全够完整洗完一整轮，没想到中途欠费了。','wǒ zhī qián chá kàn yú é hái yǒu jǐ kuài qián， yǐ wéi wán quán gòu wán zhěng xǐ wán yī zhěng lún， méi xiǎng dào zhōng tú qiàn fèi le。','Lúc trước con kiểm tra thấy còn vài đồng, cứ tưởng đủ để giặt trọn một chu trình, ai ngờ giữa chừng lại thiếu tiền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'洗衣程序分为洗涤、漂洗、脱水三段，分段扣取费用，余额不够就会中途停机。','xǐ yī chéng xù fēn wéi xǐ dí、 piǎo xǐ、 tuō shuǐ sān duàn， fēn duàn kòu qǔ fèi yòng， yú é bù gòu jiù huì zhōng tú tíng jī。','Chương trình giặt chia làm ba giai đoạn giặt, xả, vắt, mỗi giai đoạn trừ tiền riêng, không đủ tiền là máy dừng giữa chừng liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'那像我这种只洗一半就停机的情况，可以申请退还部分洗衣费用吗？','nà xiàng wǒ zhè zhǒng zhǐ xǐ yí bàn jiù tíng jī de qíng kuàng， kě yǐ shēn qǐng tuì huán bù fèn xǐ yī fèi yòng ma？','Vậy như trường hợp của con chỉ giặt được nửa chừng rồi dừng, con có thể xin hoàn lại một phần tiền giặt không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_08','V306','宿管阿姨',8,'完全可以，后勤处专门有异常扣费退款登记流程，我帮你上报。','wán quán kě yǐ， hòu qín chù zhuān mén yǒu yì cháng kòu fèi tuì kuǎn dēng jì liú chéng， wǒ bāng nǐ shàng bào。','Được hoàn toàn, phòng hậu cần có quy trình đăng ký hoàn tiền cho trường hợp bị trừ tiền bất thường, để cô báo giúp con.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Vậy làm thủ tục hoàn tiền con cần in hóa đơn giấy hay chỉ cần gửi ảnh chụp màn hình điện thoại thôi ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in giấy tờ đâu, con chỉ cần gửi ảnh chụp lúc thanh toán qua WeChat cho cô là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Con lấy ảnh gửi ngay đây ạ, khoảng bao lâu thì tiền được hoàn về ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ thứ Sáu hàng tuần là xử lý gộp các yêu cầu hoàn tiền, chậm nhất thứ Sáu tuần này tiền sẽ hoàn lại theo đúng kênh thanh toán ban đầu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Dạ con hiểu là phải chờ xử lý gộp, phiền cô giúp con đăng ký báo lên nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ thôi, lần sau giặt đồ nhớ nạp thêm chút tiền vào, kẻo lại bị dừng giữa chừng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ vâng, cảm ơn cô đã giúp đỡ nhiều ạ!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, cho em một cái bánh kếp ngũ cốc, gói mang đi giúp em nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Dạ được, em có muốn thêm xúc xích nướng, xà lách gì không?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Thêm một cây xúc xích nướng thôi, ớt cho ít lại nha, em không ăn cay được mấy.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không vấn đề, để vị cay nhẹ, hai phút là xong hà.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Phiền chị gói kín một chút giúp em, em mang về ký túc xá ăn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói cho em chắc chắn luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn hàng, có một lưu ý quan trọng về món ăn cần ghi chú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào anh/chị, anh/chị cứ nói rõ yêu cầu cụ thể, chúng em sẽ báo ngay cho bếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng nặng với đậu phộng, làm ơn tuyệt đối không cho bất kỳ chế phẩm nào từ đậu phộng vào món ăn nhé.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Dạ vâng, chúng em đã ghi chú đặc biệt là món ăn kiêng đậu phộng cho anh/chị rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây có quán bỏ qua ghi chú, suýt nữa thì xảy ra chuyện đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng em rất xin lỗi vì đã khiến anh/chị lo lắng, chúng em sẽ dặn riêng bên bếp cẩn thận ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy phiền các bạn để ý kỹ giúp mình nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, cho em hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Loại sữa chua để nhiệt độ thường này hạn dùng ba tháng, không cần bỏ tủ lạnh đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở nắp thì để được bao lâu ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, để ở nhiệt độ thường là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, chỉ cần tránh ánh nắng chiếu trực tiếp là được, tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em hiểu rồi, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn một chút nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, bạn có gì thì cứ nói thẳng nhé.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Tối nay mình phải ôn bài chuẩn bị thi, phòng các bạn hơi ồn một chút.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn, bọn mình không để ý âm lượng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau 10 giờ tối có thể giữ yên tĩnh một chút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, bọn mình nhỏ tiếng ngay đây, sau này nhất định sẽ chú ý!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thưa thầy/cô, con xin lỗi vì đã đến lớp muộn, con thực sự rất xin lỗi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại đến muộn vậy? Nguyên nhân là do đâu?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Sáng nay con ra khỏi nhà trễ, lại gặp kẹt xe nên bị trễ giờ ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải sắp xếp thời gian cho tốt, đừng để đến muộn nữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Con nhớ rồi ạ, sau này con nhất định sẽ ra khỏi nhà sớm hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, mau vào chỗ ngồi nghe giảng đi, đừng để ảnh hưởng việc học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Con cảm ơn thầy/cô đã thông cảm ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Thưa thầy/cô cố vấn, em muốn xin nghỉ phép chiều nay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được thôi, em nói qua lý do xin nghỉ xem nào.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể trì hoãn được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Thầy/cô hiểu rồi, để thầy/cô ghi nhận vào sổ điểm danh, đồng ý cho em nghỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn thầy/cô, phần bài học bị bỏ lỡ em sẽ bù đắp kịp thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhất định phải theo kịp tiến độ, đừng để nợ bài học nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi ạ, thầy/cô vất vả rồi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Chào cô, cho em xin phép chiếm dụng chút thời gian ngoài giờ học, em muốn xin cô cho gia hạn nộp bài tập ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói lý do đơn giản trước đi, quy định lớp học là không được phép trì hoãn nộp bài tập vô cớ đâu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua em bị đau bụng đường ruột đột ngột cả ngày, chóng mặt mệt lả phải nằm nghỉ, hoàn toàn không còn sức để làm bài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Cô hiểu chuyện sức khỏe không tốt, ốm đau là trường hợp đặc biệt hợp lý, nhưng việc gia hạn thì có thời hạn nghiêm ngặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Ban đầu em định chiều nay nộp đúng giờ, nhưng bây giờ vẫn còn thiếu một nửa nội dung chưa làm xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài tập chỉ được gia hạn tối đa một ngày, không thể kéo dài vô thời hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Chỉ cần gia hạn một ngày là đủ với em rồi, tối nay em sẽ thức khuya làm cho xong, đảm bảo hoàn thành đầy đủ hết nội dung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em không khỏe nên cô châm chước cho một lần, sau này dù lý do gì cũng phải cố gắng hoàn thành đúng hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc của cô rồi, lần sau em nhất định sẽ sắp xếp thời gian trước, sẽ không để xảy ra chuyện trễ hạn nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp gia hạn phải đưa đến văn phòng trước sáu giờ chiều mai, nộp trễ vẫn sẽ bị trừ điểm chuyên cần đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ đặt báo thức để nộp đúng giờ, sẽ không lỡ hạn chót đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi em nộp bài, cô sẽ ưu tiên chấm trước, chỗ nào sai cô sẽ giảng riêng cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em cảm ơn cô rất nhiều vì đã thông cảm cho tình trạng sức khỏe của em, em nhất định sẽ làm bài thật nghiêm túc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho tốt vào, đừng thức khuya quá mà hại sức khỏe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Vâng ạ, em cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Nhóm mình vẫn chưa phân công bài tập, hôm nay chốt luôn nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được đó, mình phân công theo sở trường của mỗi người thì làm sẽ hiệu quả hơn.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Tớ giỏi khoản tìm tài liệu với viết bài, còn làm PPT thì cậu ổn không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không thành vấn đề, tớ làm PPT khá lắm, cứ để phần đó cho tớ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy đến lúc thuyết trình trên lớp thì hai đứa mình cùng phối hợp nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được, làm xong tụi mình kiểm tra chéo lại cho nhau, tránh bị sai sót.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy tụi mình bắt tay vào làm phần của mình luôn nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa cô, thưa các bạn, em thật sự xin lỗi vì phần thuyết trình lần này của em chuẩn bị chưa kỹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao, cứ trình bày bình thường thôi, nói xem vấn đề nằm ở chỗ nào?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Phần chuẩn bị tài liệu trước đó của em chưa được kỹ lưỡng, nội dung còn thiếu khá nhiều chi tiết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em đã không trau chuốt nội dung thật kỹ trước khi trình bày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn nhận vấn đề như vậy là tốt rồi, lần sau chuẩn bị đầy đủ trước là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, em cảm ơn cô và các bạn đã thông cảm cho em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Chào cô, phần kiến thức cô vừa giảng ban nãy em nghe chưa hiểu lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em không hiểu? Để cô giảng lại cho em lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là logic áp dụng công thức đó ạ, em vẫn thấy hơi mơ hồ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, để cô hệ thống lại một lượt, em nghe kỹ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Vâng ạ, phiền cô bỏ công giảng giải giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, đừng ngại gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hoàn toàn rồi, em cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Chào thầy/cô, tôi muốn hỏi về quy chế phòng thi của kỳ thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Nếu có điều gì chưa rõ thì bạn cứ hỏi trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Xin hỏi trong lúc thi có được phép mang theo giấy nháp và dụng cụ học tập riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát thống nhất toàn bộ vật dụng cần dùng cho bài thi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử thì có cần tháo ra để riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải được thu gom tập trung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Tôi đã nắm rõ hết các quy định rồi, xin cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Chào cô, em muốn xác nhận lại điểm cuối kỳ môn học của em ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể là vấn đề gì vậy em?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Bài tập, chuyên cần, thi cử của em đều hoàn thành đầy đủ bình thường, nhưng hệ thống lại hiển thị chưa có điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là do hệ thống giáo vụ nhập liệu bị trục trặc, nên xảy ra lỗi dữ liệu rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo mãi là do mình sót nộp bài tập, trong lòng thấy bất an quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em yên tâm đi, cô sẽ đối chiếu thủ công theo hồ sơ lưu, rồi nhập lại điểm cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn cô rất nhiều vì đã giúp em xử lý chuyện này!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道；复核结果统一公示，具备官方效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，今天来找您，是想正式提交本次期末试卷成绩复核申请。','lǎo shī nín hǎo， jīn tiān lái zhǎo nín， shì xiǎng zhèng shì tí jiāo běn cì qī mò shì juàn chéng jì fù hé shēn qǐng。','Chào thầy/cô, hôm nay tôi đến gặp thầy/cô là để chính thức xin nộp đơn phúc khảo điểm bài thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'先坐，我先跟你确认，你清楚学校成绩复核的具体范围和规则吗？','xiān zuò， wǒ xiān gēn nǐ què rèn， nǐ qīng chǔ xué xiào chéng jì fù hé de jù tǐ fàn wéi hé guī zé ma？','Mời ngồi, để tôi xác nhận trước, bạn đã nắm rõ phạm vi và quy định phúc khảo điểm của trường chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'只听说可以核对卷面总分统计，不能重新评判答题内容，细节了解不多。','zhǐ tīng shuō kě yǐ hé duì juàn miàn zǒng fēn tǒng jì， bù néng chóng xīn píng pàn dá tí nèi róng， xì jié liǎo jiě bù duō。','Tôi chỉ nghe nói là có thể đối chiếu lại tổng điểm trên bài thi, chứ không được chấm lại nội dung bài làm, còn chi tiết thì tôi chưa rõ lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'没错，复核仅检查每道小题得分相加是否计算错误，不会更改主观题打分。','méi cuò， fù hé jǐn jiǎn chá měi dào xiǎo tí dé fēn xiāng jiā shì fǒu jì suàn cuò wù， bú huì gēng gǎi zhǔ guān tí dǎ fēn。','Đúng vậy, phúc khảo chỉ kiểm tra xem cộng điểm từng câu nhỏ có bị tính sai hay không, chứ không thay đổi điểm của các câu tự luận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'我自己对照参考答案预估的分数，和最终系统录入成绩差距很大，心里比较疑惑。','wǒ zì jǐ duì zhào cān kǎo dá àn yù gū de fēn shù， hé zuì zhōng xì tǒng lù rù chéng jì chā jù hěn dà， xīn lǐ bǐ jiào yí huò。','Tôi tự đối chiếu với đáp án tham khảo để ước tính điểm, thấy chênh lệch khá nhiều so với điểm hệ thống ghi nhận cuối cùng, nên trong lòng khá thắc mắc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'我理解你的顾虑，我可以协助你向学院教学办提交官方书面复核申请。','wǒ lǐ jiě nǐ de gù lǜ， wǒ kě yǐ xié zhù nǐ xiàng xué yuàn jiào xué bàn tí jiāo guān fāng shū miàn fù hé shēn qǐng。','Tôi hiểu băn khoăn của bạn, tôi có thể hỗ trợ bạn nộp đơn phúc khảo chính thức bằng văn bản lên phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'提交申请的时候，需要附带什么证明材料，填写专用表格吗？','tí jiāo shēn qǐng de shí hòu， xū yào fù dài shén me zhèng míng cái liào， tián xiě zhuān yòng biǎo gé ma？','Vậy khi nộp đơn thì cần đính kèm giấy tờ chứng minh gì không, có phải điền vào mẫu đơn riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_08','V319','老师',8,'我这边给你打印统一的复核申请表，填写姓名、学号、科目和申请理由即可。','wǒ zhè biān gěi nǐ dǎ yìn tǒng yī de fù hé shēn qǐng biǎo， tián xiě xìng míng、 xué hào、 kē mù hé shēn qǐng lǐ yóu jí kě。','Bên tôi sẽ in cho bạn mẫu đơn phúc khảo chung, chỉ cần điền họ tên, mã số sinh viên, môn học và lý do xin phúc khảo là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_09','V319','阮明',9,'请问提交申请表之后，大概多久可以出具最终复核结果呢？','qǐng wèn tí jiāo shēn qǐng biǎo zhī hòu， dà gài duō jiǔ kě yǐ chū jù zuì zhōng fù hé jié guǒ ne？','Xin hỏi sau khi nộp đơn thì khoảng bao lâu sẽ có kết quả phúc khảo cuối cùng ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_10','V319','老师',10,'学院统一收集申请，三个工作日内完成卷面核对并公示修正后的成绩。','xué yuàn tǒng yī shōu jí shēn qǐng， sān gè gōng zuò rì nèi wán chéng juàn miàn hé duì bìng gōng shì xiū zhèng hòu de chéng jì。','Khoa sẽ tập hợp đơn thống nhất, trong vòng ba ngày làm việc sẽ hoàn tất đối chiếu bài thi và công bố điểm đã được chỉnh sửa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_11','V319','阮明',11,'如果复核后分数有调整，系统成绩会同步更新对吧？','rú guǒ fù hé hòu fēn shù yǒu tiáo zhěng， xì tǒng chéng jì huì tóng bù gēng xīn duì ba？','Nếu sau phúc khảo điểm có thay đổi thì điểm trên hệ thống sẽ được cập nhật đồng bộ đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_12','V319','老师',12,'是的，核对出计算失误会直接修改教务系统内你的期末分数。','shì de， hé duì chū jì suàn shī wù huì zhí jiē xiū gǎi jiào wù xì tǒng nèi nǐ de qī mò fēn shù。','Đúng vậy, nếu phát hiện sai sót khi tính điểm thì sẽ sửa trực tiếp điểm cuối kỳ của bạn trên hệ thống giáo vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_13','V319','阮明',13,'我现在填写申请表，麻烦老师帮忙转交教学办。','wǒ xiàn zài tián xiě shēn qǐng biǎo， má fán lǎo shī bāng máng zhuǎn jiāo jiào xué bàn。','Vậy tôi điền đơn ngay bây giờ, phiền thầy/cô giúp chuyển lên phòng đào tạo giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_14','V319','老师',14,'放心，流程我全程跟进，有结果第一时间通知你。','fàng xīn， liú chéng wǒ quán chéng gēn jìn， yǒu jié guǒ dì yī shí jiān tōng zhī nǐ。','Yên tâm đi, tôi sẽ theo dõi toàn bộ quy trình, có kết quả sẽ báo cho bạn ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_15','V319','阮明',15,'辛苦老师费心办理，非常感谢！','xīn kǔ lǎo shī fèi xīn bàn lǐ， fēi cháng gǎn xiè！','Cảm ơn thầy/cô đã vất vả lo liệu giúp tôi, tôi thật sự rất biết ơn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ ơi, hôm qua tớ xin nghỉ nên bị lỡ buổi học, cho tớ mượn vở ghi chép trên lớp của cậu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Được chứ, tớ ghi khá chi tiết đó, chỗ nào quan trọng khó hiểu tớ đều đánh dấu hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Tuyệt quá, đúng lúc tớ bị lỡ mất phần kiến thức quan trọng nhất luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ từ từ xem, xem xong trả lại tớ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều lắm luôn, chỗ nào không hiểu tớ hỏi lại cậu nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không vấn đề gì cả, bạn bè với nhau vốn dĩ phải giúp đỡ nhau mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng ghê luôn á!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào bạn, tôi muốn đặt lịch khám nội khoa hôm nay trên ứng dụng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Chào anh/chị, anh/chị muốn đặt khám thường hay khám chuyên gia ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Khám thường thôi, tôi chỉ hơi chóng mặt và mệt mỏi một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Rất xin lỗi anh/chị, hôm nay các suất khám thường khoa nội đã kín hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn suất trống không?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn nhiều suất trống, để tôi hướng dẫn anh/chị đặt nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Được đó, phiền bạn chỉ giúp tôi thao tác với!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào bạn, dạo này tôi hay bị chóng mặt, ngủ không ngon, vậy nên khám khoa nào đây?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Với triệu chứng này của bạn thì khám khoa thần kinh nội là hợp lý nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy giúp tôi đăng ký khám thường chiều nay nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được rồi, bạn thanh toán bằng bảo hiểm y tế hay tự chi trả ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Tôi dùng bảo hiểm y tế học sinh sinh viên để thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Bạn đã đăng ký khám thành công, mời bạn lên phòng khám tầng hai chờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Được rồi, cảm ơn bạn nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Chào bác sĩ, mấy ngày nay em cứ bị chóng mặt, người mệt rã rời.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Em bị chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng thôi ạ, nhất là buổi tối, với lại em hay mất ngủ, khó ngủ lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Em có bị sốt, buồn nôn hay khó chịu gì khác không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Dạ không ạ, chỉ có mỗi hai triệu chứng là chóng mặt và mệt mỏi thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Tôi hiểu sơ bộ rồi, để tôi khám qua cho em một chút nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Dạ vâng, phiền bác sĩ giúp em với ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Thưa bác sĩ, tôi cần báo trước với bác sĩ về tiền sử dị ứng thuốc của mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Vâng, cụ thể ông/bà dị ứng với loại thuốc nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Tôi bị dị ứng với các loại thuốc thuộc nhóm penicillin, tuyệt đối không được dùng loại này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Tôi đã ghi nhận, khi kê đơn sẽ tránh hoàn toàn các thuốc gây dị ứng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây phản ứng dị ứng của tôi rất nghiêm trọng, nên tôi đặc biệt thận trọng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Tôi hiểu, an toàn dùng thuốc là ưu tiên hàng đầu, ông/bà cứ yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Cảm ơn bác sĩ đã tận tâm và chu đáo!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào bạn, đây là đơn thuốc của tôi, phiền bạn lấy thuốc giúp tôi với.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Vâng, anh/chị chờ chút, tôi kiểm tra lại thông tin thuốc đã nhé.',NULL);
